CREATE TABLE IF NOT EXISTS usuarios (id INT UNSIGNED AUTO_INCREMENT PRIMARY KEY,name VARCHAR(120) NOT NULL,email VARCHAR(190) NOT NULL UNIQUE,phone VARCHAR(40),password VARCHAR(255) NOT NULL,role ENUM('cliente','admin') NOT NULL DEFAULT 'cliente',status ENUM('active','blocked') NOT NULL DEFAULT 'active',created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE IF NOT EXISTS semanas_reserva (id INT UNSIGNED AUTO_INCREMENT PRIMARY KEY,label VARCHAR(120) NOT NULL,delivery_date DATE NOT NULL,total_boxes INT UNSIGNED NOT NULL DEFAULT 0,available_males INT UNSIGNED NOT NULL DEFAULT 0,available_females INT UNSIGNED NOT NULL DEFAULT 0,status ENUM('active','closed') NOT NULL DEFAULT 'active',created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE IF NOT EXISTS reservas (id INT UNSIGNED AUTO_INCREMENT PRIMARY KEY,code VARCHAR(24) NOT NULL UNIQUE,user_id INT UNSIGNED NOT NULL,week_id INT UNSIGNED NULL,customer_name VARCHAR(120) NOT NULL,phone VARCHAR(40) NOT NULL,email VARCHAR(190) NOT NULL,delivery_date DATE NOT NULL,quantity INT UNSIGNED NOT NULL,notes TEXT,status ENUM('pending','confirmed','cancelled') NOT NULL DEFAULT 'pending',created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,INDEX(user_id),CONSTRAINT fk_res_user FOREIGN KEY(user_id) REFERENCES usuarios(id)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
